SELECT 
    qualification as '资质等级',
    COUNT(*) as '供应商数量',
    GROUP_CONCAT(DISTINCT industry) as '涉及行业'
FROM suppliers 
GROUP BY qualification 
ORDER BY qualification;

SELECT 
    region as '地区',
    COUNT(*) as '供应商数量'
FROM suppliers 
GROUP BY region 
ORDER BY COUNT(*) DESC;
